const response = $input.first().json;
const originalInput = $node['Process Item Webhook'].json.body?.input || '';

try {
  const aiText = response.output || response.text || '';
  const jsonMatch = aiText.match(/\{[\s\S]*\}/);
  const parsed = jsonMatch ? JSON.parse(jsonMatch[0]) : null;

  return {
    title: parsed?.title || originalInput.substring(0, 100),
    summary: parsed?.summary || '',
    category: parsed?.category || 'Inbox',
    item_type: parsed?.item_type || (originalInput.startsWith('http') ? 'link' : 'note'),
    tags: parsed?.tags || [],
    url: originalInput.startsWith('http') ? originalInput : null
  };
} catch (e) {
  return {
    title: originalInput.substring(0, 100),
    summary: '',
    category: 'Inbox',
    item_type: originalInput.startsWith('http') ? 'link' : 'note',
    tags: [],
    url: originalInput.startsWith('http') ? originalInput : null
  };
}
